"""Publish a dated partial-run mechanism snapshot, without candidate-month scores."""
from pathlib import Path
import argparse,json,shutil,sys
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from PIL import Image
ROOT=Path(__file__).resolve().parents[1];sys.path[:0]=[str(ROOT),str(ROOT/'scripts')]
from local_benchmark_protocol import file_hash,write_json


def publish(progress,diagnosis,out):
    progress=progress.resolve();diagnosis=diagnosis.resolve();out=out.resolve();out.mkdir(parents=True,exist_ok=True)
    snapshot=json.loads((progress/'latest.json').read_text());water=json.loads((diagnosis/'diagnosis.json').read_text())
    for name,digest in snapshot['input_sha256'].items():assert file_hash(ROOT/name)==digest
    for name,digest in water['input_sha256'].items():assert file_hash(ROOT/name)==digest
    trace=ROOT/snapshot['figure'];assert file_hash(trace)==snapshot['figure_sha256'];assert file_hash(diagnosis/'water_supply.png')==water['figure_sha256']
    regions=list(water['summaries']);fig,axes=plt.subplots(1,len(regions),figsize=(7*len(regions),5),squeeze=False);terms=['evaporation','net_column_import','vapor_storage_change','rain'];labels=['Evaporation','Net import','Vapor storage\nchange','Rain'];table=[]
    for ax,region in zip(axes[0],regions):
        summary=water['summaries'][region]
        for name,color,offset in [('wet','#207fa5',-.18),('dry','#cf9438',.18)]:
            values=summary['branches'][name];ax.bar(np.arange(4)+offset,[values[k] for k in terms],.35,label=name,color=color)
            table.append(dict(region=region,branch=name,start_day=summary['start_after_day']+1,end_day=summary['end_day'],**values))
        ax.axhline(0,color='#444',lw=.8);ax.set_xticks(np.arange(4),labels);ax.set_ylabel('Mean mm/day on fixed scoring footprints');ax.set_title(region.replace('_',' ')+f" · days {summary['start_after_day']+1}–{summary['end_day']}");ax.legend();ax.grid(axis='y',alpha=.2)
    fig.suptitle('Water supply during the shared available evaluation interval',fontsize=13);fig.text(.5,.01,'Rain = evaporation + net import − vapor storage change • partial interval, not a full-month skill score',ha='center',fontsize=9);fig.tight_layout(rect=(0,.05,1,.93));fig.savefig(out/'monthly_water_budget.png',dpi=160);plt.close(fig)
    dest=ROOT/'atlases/climate_accuracy/data';shutil.copyfile(trace,dest/'monthly_rainfall_progress.png');shutil.copyfile(diagnosis/'water_supply.png',dest/'monthly_water_supply.png');shutil.copyfile(out/'monthly_water_budget.png',dest/'monthly_water_budget.png');shutil.copyfile(diagnosis/'water_fields.npz',dest/'monthly_water_fields.npz')
    result=dict(status='partial_month_progress_and_water_mechanism_snapshot',daily_progress=snapshot,water_diagnosis=water,table=table,figure_sha256={n:file_hash(dest/n) for n in ['monthly_rainfall_progress.png','monthly_water_supply.png','monthly_water_budget.png']},publisher_sha256=file_hash(Path(__file__)),candidate_month_score=None,new_integrations_started_by_publication=0,physical_adoption=False,recalibration=False,scope='Read-only dated snapshot, all shared available evaluation days. Inferred store identities are not water-origin tracers, and partial-period rain is not scored as a complete month.')
    write_json(out/'publication.json',result);write_json(dest/'monthly_water_progress.json',result)
    figures=''
    for name,caption in [('monthly_rainfall_progress.png','Available daily traces. Shading marks the14-day prelude; the green guide is the observed monthly climatological mean, not daily weather.'),('monthly_water_budget.png','Conserved-store water identities on the shared available evaluation interval. Negative net import means net export.'),('monthly_water_supply.png','Full regional fields with common wet/dry scales; circles identify the fixed scored cells. Large perimeter fluxes remain visible.')]:
        with Image.open(dest/name) as im:w,h=im.size
        figures+=f'<figure><a href="data/{name}"><img src="data/{name}" width="{w}" height="{h}" loading="lazy" alt="{caption}"></a><figcaption>{caption}</figcaption></figure>'
    htmlrows=''.join('<tr>'+''.join(f'<td>{r[k]:.3f}</td>' if isinstance(r[k],float) else f'<td>{r[k]}</td>' for k in ['region','branch','start_day','end_day','rain','evaporation','net_column_import','vapor_storage_change'])+'</tr>' for r in table)
    section=f'''<!--monthly-water-progress-start--><section aria-labelledby="monthly-water-progress-h"><h2 id="monthly-water-progress-h">Rainfall trial progress and water-supply diagnosis</h2><p>This is a dated snapshot of the ongoing monthly trials. Every available daily water and energy budget is reconstructed from the saved states. Complete31-day candidate losses remain pending; the plotted interval is never substituted for a full-month score.</p>{figures}<div class="table"><table><caption>Common available post-prelude interval, rates in mm/day on frozen scoring footprints</caption><thead><tr><th>Region</th><th>Start</th><th>First day</th><th>Last day</th><th>Rain</th><th>Evaporation</th><th>Net import</th><th>Vapor change</th></tr></thead><tbody>{htmlrows}</tbody></table></div><p>The wet India branch is losing water through net horizontal export over its scoring area, while its surface store is being depleted. The dry branch has almost no rain or evaporation there. This directs attention to circulation and moisture delivery as well as the surface-water treatment. It does not establish a unique cause: these branches differ in thermal capacity and evolving temperature too, and no water-origin tracer is present.</p><p>The environment interrupted both India worker processes. Their checkpoints were retained; separate one-day recovery checks reproduced every saved state field byte exactly before continuation. Daily prefix ledgers are preserved. Per-step prefix histories were not flushed and are not fabricated. Interrupted process segments and replay diagnostics are reported separately from initialized trajectories.</p><p class="note">No calibration, pooled candidate-month score, equilibrium claim or new physics adoption. The three summer region/month pairs remain development cases under fixed simulated lateral reservoirs. Normal atlas climate, biome and population fields are unchanged.</p><p><a href="data/monthly_water_progress.json">Daily state checks, original input hashes and water diagnosis</a> · <a href="data/monthly_water_fields.npz">Partial-interval water fields</a> · <a href="../../reports/MONTHLY_WATER_PROGRESS_20261029.md">Interpretation and recovery record</a></p></section><!--monthly-water-progress-end-->'''
    page=ROOT/'atlases/climate_accuracy/index.html';text=page.read_text();start,end='<!--monthly-water-progress-start-->','<!--monthly-water-progress-end-->'
    if start in text:before,tail=text.split(start,1);_,after=tail.split(end,1);text=before+section+after
    else:text=text.replace('<!--research-list-start-->',section+'\n<!--research-list-start-->',1)
    page.write_text(text)
    report='# Monthly rainfall progress and moisture-supply diagnosis\n\nThis snapshot is partial. No incomplete-month candidate error or pooled score is produced. The committed31-day scoring objective, masks and model parameters remain unchanged.\n\n| Region | Branch | Days | Rain | Evaporation | Net import | Vapor change |\n|---|---|---|---:|---:|---:|---:|\n'
    for r in table:report+=f'| {r["region"]} | {r["branch"]} | {r["start_day"]}–{r["end_day"]} | {r["rain"]:.4f} | {r["evaporation"]:.4f} | {r["net_column_import"]:.4f} | {r["vapor_storage_change"]:.4f} |\n'
    report+='\nRates are mm/day on fixed projection-area-weighted scoring footprints. For this liquid-only model, E=P−Δsoil and net horizontal column import=Δ(vapor+soil), with stores divided by interval length. Consequently P=E+import−Δvapor. This is a conserved-store diagnosis, not an independent source tracer or a rainfall-conversion efficiency measurement.\n\nThe wet India scoring area exports water while depleting its surface store. The dry branch has almost no rain there. Moisture delivery/circulation and land-surface supply warrant investigation before trying to fix rainfall by changing conversion coefficients. No unique causal attribution: starting water also changes thermal capacity, skin temperature and circulation. Missing terrain and nonlinear momentum remain plausible structural limitations, not demonstrated causes from this snapshot.\n\nAn environment restart interrupted the original India processes at wet day29 and dry day30. Every saved daily prefix was retained and checked against its hash and independent energy/water ledger. Three isolated one-day replay segments were retained, including a repeated wet replay after removing a CLI-global dependency. Both branches reproduce all10 subsequent checkpoint fields byte exactly. These segments add zero new Earth initializations; the two process interruptions are separately recorded. Original per-step histories before interruption were not flushed. They are unavailable rather than fabricated. All future daily checkpoints and continuation step histories are retained.\n\nRecovery milestone41f77a71 was committed and pushed before the monthly workers resumed. The frozen model sources, forcing, calendar, time step, masks and objective remain unchanged. Reused regional summer tests are not independent global/annual validation. No recalibration, physical adoption, normal-atlas climate changes or claim of optimizer convergence.\n'
    (ROOT/'reports/MONTHLY_WATER_PROGRESS_20261029.md').write_text(report)
    print(json.dumps(dict(table=table,candidate_month_score=None),indent=2))


if __name__=='__main__':
    p=argparse.ArgumentParser(description=__doc__);p.add_argument('--progress',type=Path,required=True);p.add_argument('--diagnosis',type=Path,required=True);p.add_argument('--out',type=Path,required=True);a=p.parse_args();publish(a.progress,a.diagnosis,a.out)
